// scripts/build-styles.ts — the ONE component-style build face (W2267.4.2.2 +
// W2267.8): compiles the same-name .scss sources through @klh/design-ui's
// compileStylesheet into generated CSS string modules the Lit components
// adopt as static styles (or, for page-level sheets like decisions, a plain
// string the page interpolates). Sass computes structure at build time; the
// theme rides the kernel layer's --klh-* custom properties at runtime, so
// every generated sheet is theme-free (semantic tokens only). package.json's
// build:styles runs this file verbatim; editing a generated file is always
// wrong — edit the .scss.
import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { compileStylesheet } from "@klh/design-ui/build/scss-plugin.ts";

const ROOT = resolve(import.meta.dir, "..");

/** Same-name pairs: hooks/board-html/<name>.scss → <name>-css.ts exporting
 *  either <ENTITY>_STYLES (a Lit CSSResult, `lit: true`) or a plain string
 *  entity interpolated into page CSS (`lit: false`). */
const PAIRS = [
	{
		scss: "hooks/board-html/klh-task-card.scss",
		out: "hooks/board-html/klh-task-card-css.ts",
		entity: "TASK_CARD_STYLES",
		lit: true,
	},
	{
		scss: "hooks/board-html/klh-card-activity.scss",
		out: "hooks/board-html/klh-card-activity-css.ts",
		entity: "CARD_ACTIVITY_STYLES",
		lit: true,
	},
	{
		scss: "hooks/board-html/decisions.scss",
		out: "hooks/board-html/decisions-css.ts",
		entity: "DECISIONS_CSS",
		lit: false,
	},
] as const;

/** Compile every same-name .scss → its generated style module. */
export function buildComponentStyles(): string[] {
	return PAIRS.map((p) => {
		const css = compileStylesheet(join(ROOT, p.scss));
		const head = p.lit
			? [
					'import { css, unsafeCSS } from "lit";\n',
					`export const ${p.entity} = css\`\${unsafeCSS(`,
				].join("")
			: `export const ${p.entity} = `;
		const mod = [
			`// GENERATED by scripts/build-styles.ts — edit ${p.scss.split("/").pop()}, never this file.\n`,
			head,
			JSON.stringify(css),
			p.lit ? ")}`;\n" : ";\n",
		].join("");
		writeFileSync(join(ROOT, p.out), mod);
		return p.out;
	});
}

if (import.meta.main) {
	const outs = buildComponentStyles();
	for (const o of outs) console.log(`component styles → ${o}`);
}
